-- postgresql.conf: shared_preload_libraries = 'pgaudit'
CREATE EXTENSION pgaudit;

CREATE ROLE auditor NOLOGIN;
ALTER SYSTEM SET pgaudit.role = 'auditor';
ALTER SYSTEM SET pgaudit.log = 'ddl, role';   -- session classes
ALTER SYSTEM SET pgaudit.log_parameter = off; -- keep values out of the log
SELECT pg_reload_conf();

-- Anything done to this table is now audited, for every user
GRANT SELECT, INSERT, UPDATE, DELETE ON app.customers TO auditor;

